from pathlib import Path
import subprocess,json,hashlib,time,statistics,random,shutil
p=Path(__file__).parent;o=p/'final_gate';o.mkdir(exist_ok=True)
vs={'baseline':p/'baseline/library.hpp','control':p/'baseline/library.hpp','candidate':p/'gcc_sequential.hpp'}
cs={'gcc152':['/usr/bin/g++'],'gcc152native':['/usr/bin/g++','-march=native'],'gcc153':['/usr/local/bin/g++'],'gcc153native':['/usr/local/bin/g++','-march=native'],'clang':['clang++','--gcc-install-dir=/usr/lib/gcc/x86_64-linux-gnu/15']}
main=(p/'baseline/main.cpp').read_text().replace('#include "Verify/current/common/fast_io.hpp"',(p/'baseline/fast_io.hpp').read_text());builds=[]
for cc,compiler in cs.items():
 for v,h in vs.items():
  for typ in ['api','main']:
   src=p/'api_extra.cpp'
   if typ=='main':src=o/(v+'.cpp');src.write_text('#define SKIP_RUNTIME_CHECKS\n'+h.read_text()+main)
   cmd=[*compiler,'-std=c++23','-O2',f'-DSOURCE="{h}"',str(src),'-o',str(o/f'{cc}-{v}-{typ}')]
   if typ=='api':cmd.insert(2,'-DSKIP_RUNTIME_CHECKS')
   a=subprocess.run(cmd,capture_output=True,text=True);assert a.returncode==0,a.stderr;builds.append(dict(cc=cc,variant=v,type=typ,command=cmd,header_sha256=hashlib.sha256(h.read_bytes()).hexdigest()))
 print('built',cc,flush=True)
(o/'builds.json').write_text(json.dumps(builds,indent=2));active=o/'run-active';rng=random.Random(9917);raw=[]
def api(cc,v,n,mode,reps):
 shutil.copyfile(o/f'{cc}-{v}-api',active);active.chmod(0o755)
 a=subprocess.run(['taskset','-c','12',str(active),str(n),str(mode),str(reps)],capture_output=True,text=True);assert a.returncode==0,a.stderr;ns,s=map(int,a.stdout.split());return ns,s
for cc in cs:
 for n in [32,4097,131072,1048576]:
  for mode in [0,1,2,3,4,5,6,7]:
   if n==1048576 and mode not in [2,4,7]:continue
   pilot=max(1,10000//n);ns,_=api(cc,'baseline',n,mode,pilot);reps=max(1,min(1000000,int(pilot*25e6/max(ns,1))))
   sums=set()
   for r in range(7):
    order=list(vs);rng.shuffle(order)
    for v in order:
     ns,s=api(cc,v,n,mode,reps);sums.add(s);raw.append(dict(cc=cc,n=n,mode=mode,variant=v,rep=r,repeats=reps,ns=ns,checksum=s))
   assert len(sums)==1,(cc,n,mode,sums)
 print('api',cc,flush=True)
(o/'api-raw.json').write_text(json.dumps(raw,indent=2));summary=[]
for cc in cs:
 for n,mode in sorted({(x['n'],x['mode']) for x in raw if x['cc']==cc}):
  med={v:statistics.median(x['ns'] for x in raw if x['cc']==cc and x['n']==n and x['mode']==mode and x['variant']==v) for v in vs}
  summary.append(dict(cc=cc,n=n,mode=mode,median_ns=med,ratios={v:med[v]/med['baseline'] for v in vs}))
(o/'api-summary.json').write_text(json.dumps(summary,indent=2))
mr=[];ins=Path('/tmp/persistent_round2_20261030/inputs');outs=Path('/tmp/persistent_round2_20261030/outputs')
for cc in cs:
 for ip in sorted(ins.glob('*.in')):
  expected=(outs/(ip.stem+'.out')).read_bytes().split()
  for r in range(7 if ip.stem in ['random_00','max_random_02','conchon_filliatre_tle_00'] else 3):
   order=list(vs);rng.shuffle(order)
   for v in order:
    shutil.copyfile(o/f'{cc}-{v}-main',active);active.chmod(0o755)
    with ip.open('rb') as f:
     t=time.perf_counter_ns();a=subprocess.run(['taskset','-c','12',str(active)],stdin=f,capture_output=True);ns=time.perf_counter_ns()-t
    assert a.returncode==0 and a.stdout.split()==expected,(cc,ip,v,a.stderr)
    mr.append(dict(cc=cc,case=ip.stem,rep=r,variant=v,ns=ns,output_sha256=hashlib.sha256(a.stdout).hexdigest()))
 print('main',cc,flush=True)
(o/'main-raw.json').write_text(json.dumps(mr,indent=2));summ=[]
for cc in cs:
 for case in sorted({x['case'] for x in mr if x['cc']==cc}):
  med={v:statistics.median(x['ns'] for x in mr if x['cc']==cc and x['case']==case and x['variant']==v) for v in vs};summ.append(dict(cc=cc,case=case,median_ns=med,ratios={v:med[v]/med['baseline'] for v in vs}))
(o/'main-summary.json').write_text(json.dumps(summ,indent=2));print('done',flush=True)

