from pathlib import Path
import subprocess,json,statistics,random,shutil
p=Path(__file__).parent;o=p/'groups_screen';o.mkdir(exist_ok=True)
vs={'baseline':p/'baseline/library.hpp','control':p/'baseline/library.hpp','memo':p/'review/groups_memo.hpp'}
cs={'gcc152':['/usr/bin/g++'],'gcc152native':['/usr/bin/g++','-march=native'],'gcc153':['/usr/local/bin/g++'],'gcc153native':['/usr/local/bin/g++','-march=native']}
builds=[]
for cc,compiler in cs.items():
 for v,h in vs.items():
  cmd=[*compiler,'-std=c++23','-O2','-DSKIP_RUNTIME_CHECKS',f'-DSIRKIT_RUF_SOURCE="{h}"','Verify/current/tests/rollback_union_groups_performance_benchmark.cpp','-o',str(o/f'{cc}-{v}')]
  a=subprocess.run(cmd,capture_output=True,text=True);assert a.returncode==0,a.stderr;builds.append(dict(command=cmd))
(o/'builds.json').write_text(json.dumps(builds,indent=2));raw=[];rng=random.Random(55);active=o/'run-active'
def run(cc,v,n,components,reps):
 shutil.copyfile(o/f'{cc}-{v}',active);active.chmod(0o755)
 a=subprocess.run(['taskset','-c','12',str(active),str(n),str(components),str(reps)],capture_output=True,text=True);assert a.returncode==0,a.stderr
 ns,s=a.stdout.split();return float(ns),int(s)
for cc in cs:
 for n in [32,4096,131072]:
  for size in [2,4,16,256]:
   if size>=n:continue
   pilot=max(1,20000//n);ms,_=run(cc,'baseline',n,n//size,pilot);reps=max(1,int(pilot*20/max(ms,.001)))
   sums=set()
   for r in range(5):
    order=list(vs);rng.shuffle(order)
    for v in order:
     ms,s=run(cc,v,n,n//size,reps);sums.add(s);raw.append(dict(cc=cc,n=n,size=size,reps=reps,variant=v,ms=ms,checksum=s))
   assert len(sums)==1
   med={v:statistics.median(x['ms'] for x in raw if x['cc']==cc and x['n']==n and x['size']==size and x['variant']==v) for v in vs};print(cc,n,size,{v:round(med[v]/med['baseline'],3) for v in vs},flush=True)
(o/'raw.json').write_text(json.dumps(raw,indent=2))

