   row=dict(cc=cc,n=n,mode=mode,median_ns=m,ratios={v:m[v]/m['baseline'] for v in variants});summary.append(row)
   print(cc,n,mode,{v:round(z,3) for v,z in row['ratios'].items()},flush=True)
(o/'summary.json').write_text(json.dumps(summary,indent=2))
